# Terraform Module: `app-infra`

Scope of this deliverable: **S3 bucket, RDS PostgreSQL, IAM service-account identity**, plus the environment wiring (dev/prod). EKS/CloudFront from the canonical spine are separate modules in the same root; hooks are noted at the end.

```
.
├── modules/
│   └── app-infra/
│       ├── versions.tf
│       ├── variables.tf
│       ├── kms.tf
│       ├── s3.tf
│       ├── rds.tf
│       ├── iam.tf
│       ├── secrets.tf
│       └── outputs.tf
└── envs/
    ├── main.tf
    ├── providers.tf
    ├── variables.tf
    ├── outputs.tf
    ├── backend-dev.hcl
    ├── backend-prod.hcl
    ├── dev.tfvars
    └── prod.tfvars
```

---

## `modules/app-infra/versions.tf`

```hcl
terraform {
  required_version = ">= 1.6.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.40"
      # Caller must pass both: primary region + replica region (us-west-2).
      configuration_aliases = [aws.replica]
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}
```

---

## `modules/app-infra/variables.tf`

```hcl
variable "name_prefix" {
  description = "Prefix for all resource names, e.g. \"acme-web\"."
  type        = string
}

variable "environment" {
  description = "Environment name. Drives naming, tagging and guardrails."
  type        = string
  validation {
    condition     = contains(["dev", "prod"], var.environment)
    error_message = "environment must be one of: dev, prod."
  }
}

variable "tags" {
  description = "Tags applied to every taggable resource."
  type        = map(string)
  default     = {}
}

# ---------------------------------------------------------------- encryption

variable "use_kms" {
  description = "Use a customer-managed KMS key for S3 + RDS + Secrets Manager. When false, S3 uses AES-256 (SSE-S3) and RDS uses the AWS-managed key."
  type        = bool
  default     = false
}

# ----------------------------------------------------------------------- s3

variable "enable_replication" {
  description = "Enable cross-region replication of the assets bucket into var.replica_region."
  type        = bool
  default     = false
}

variable "noncurrent_version_expiration_days" {
  description = "Days after which noncurrent object versions are expired."
  type        = number
  default     = 90
}

# ---------------------------------------------------------------------- rds

variable "db_name" {
  description = "Initial database name."
  type        = string
  default     = "appdb"
}

variable "db_username" {
  description = "Master username. Password is generated and stored in Secrets Manager; it is never written to tfvars."
  type        = string
  default     = "appadmin"
}

variable "db_instance_class" {
  description = "RDS instance class."
  type        = string
}

variable "db_allocated_storage" {
  description = "Allocated storage in GiB."
  type        = number
  default     = 20
}

variable "db_max_allocated_storage" {
  description = "Upper bound for storage autoscaling. Set equal to db_allocated_storage to disable."
  type        = number
  default     = 100
}

variable "db_engine_version" {
  description = "PostgreSQL engine version."
  type        = string
  default     = "16.3"
}

variable "db_multi_az" {
  description = "Deploy the instance across multiple AZs."
  type        = bool
  default     = false
}

variable "db_backup_retention_days" {
  description = "Automated backup retention in days. Acceptance criteria require >= 7."
  type        = number
  default     = 7
  validation {
    condition     = var.db_backup_retention_days >= 7
    error_message = "db_backup_retention_days must be >= 7."
  }
}

variable "db_subnet_ids" {
  description = "Private subnet IDs for the DB subnet group. Must span >= 2 AZs."
  type        = list(string)
  validation {
    condition     = length(var.db_subnet_ids) >= 2
    error_message = "Provide at least two subnets in distinct AZs."
  }
}

variable "vpc_id" {
  description = "VPC that hosts the database."
  type        = string
}

variable "db_client_security_group_ids" {
  description = "Security groups permitted to reach Postgres on 5432 (e.g. the EKS node group SG). No CIDR ingress is configured by design."
  type        = list(string)
  default     = []
}

# ---------------------------------------------------------------------- iam

variable "create_iam_user" {
  description = "Create an IAM user with programmatic access. Intended for dev only; blocked on prod."
  type        = bool
  default     = false
}

variable "oidc_provider_arn" {
  description = "ARN of the cluster IRSA OIDC provider. Required when create_iam_user is false."
  type        = string
  default     = null
}

variable "oidc_provider_url" {
  description = "OIDC issuer URL without the https:// scheme, e.g. oidc.eks.eu-central-1.amazonaws.com/id/ABC123."
  type        = string
  default     = null
}

variable "service_account" {
  description = "Kubernetes service account trusted by the IAM role."
  type = object({
    namespace = string
    name      = string
  })
  default = {
    namespace = "default"
    name      = "app"
  }
}
```

---

## `modules/app-infra/kms.tf`

```hcl
locals {
  is_prod = var.environment == "prod"
  name    = "${var.name_prefix}-${var.environment}"

  tags = merge(var.tags, {
    Environment = var.environment
    ManagedBy   = "terraform"
    Module      = "app-infra"
  })
}

# Hard guardrails encoded as preconditions rather than documentation.
resource "terraform_data" "guardrails" {
  lifecycle {
    precondition {
      condition     = !(local.is_prod && var.create_iam_user)
      error_message = "Long-lived IAM user credentials are not permitted in prod; use OIDC/IRSA."
    }
    precondition {
      condition     = !local.is_prod || var.use_kms
      error_message = "prod must use a customer-managed KMS key (use_kms = true)."
    }
    precondition {
      condition     = !local.is_prod || var.db_multi_az
      error_message = "prod must run Multi-AZ."
    }
    precondition {
      condition     = var.create_iam_user || (var.oidc_provider_arn != null && var.oidc_provider_url != null)
      error_message = "oidc_provider_arn and oidc_provider_url are required when create_iam_user = false."
    }
  }
}

resource "aws_kms_key" "this" {
  count = var.use_kms ? 1 : 0

  description             = "${local.name} data encryption key"
  enable_key_rotation     = true
  deletion_window_in_days = 30
  multi_region            = var.enable_replication
  tags                    = local.tags
}

resource "aws_kms_alias" "this" {
  count         = var.use_kms ? 1 : 0
  name          = "alias/${local.name}"
  target_key_id = aws_kms_key.this[0].key_id
}

# Replica-region key, required because KMS keys are regional and the
# replication target must be encrypted with a key local to us-west-2.
resource "aws_kms_key" "replica" {
  count    = var.enable_replication && var.use_kms ? 1 : 0
  provider = aws.replica

  description             = "${local.name} replica data encryption key"
  enable_key_rotation     = true
  deletion_window_in_days = 30
  tags                    = local.tags
}

locals {
  kms_key_arn         = try(aws_kms_key.this[0].arn, null)
  replica_kms_key_arn = try(aws_kms_key.replica[0].arn, null)
}
```

