## `modules/app-infra/iam.tf`

```hcl
# Least-privilege application permissions. No wildcard actions, resources
# scoped to exactly this environment's bucket and secret.
data "aws_iam_policy_document" "app" {
  statement {
    sid    = "ReadWriteAssets"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:PutObject",
      "s3:DeleteObject",
      "s3:GetObjectVersion",
    ]
    resources = ["${aws_s3_bucket.assets.arn}/*"]
  }

  statement {
    sid       = "ListAssetsBucket"
    effect    = "Allow"
    actions   = ["s3:ListBucket", "s3:GetBucketLocation"]
    resources = [aws_s3_bucket.assets.arn]
  }

  statement {
    sid       = "ReadDbSecret"
    effect    = "Allow"
    actions   = ["secretsmanager:GetSecretValue", "secretsmanager:DescribeSecret"]
    resources = [aws_secretsmanager_secret.db.arn]
  }

  dynamic "statement" {
    for_each = var.use_kms ? [1] : []
    content {
      sid       = "UseDataKey"
      effect    = "Allow"
      actions   = ["kms:Decrypt", "kms:GenerateDataKey"]
      resources = [local.kms_key_arn]
    }
  }
}

resource "aws_iam_policy" "app" {
  name        = "${local.name}-app"
  description = "Application access to assets bucket and DB secret"
  policy      = data.aws_iam_policy_document.app.json
  tags        = local.tags
}

# ------------------------------------------------- prod: IRSA role, no creds

data "aws_iam_policy_document" "irsa_assume" {
  count = var.create_iam_user ? 0 : 1

  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = [var.oidc_provider_arn]
    }

    condition {
      test     = "StringEquals"
      variable = "${var.oidc_provider_url}:sub"
      values   = ["system:serviceaccount:${var.service_account.namespace}:${var.service_account.name}"]
    }

    condition {
      test     = "StringEquals"
      variable = "${var.oidc_provider_url}:aud"
      values   = ["sts.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "app" {
  count = var.create_iam_user ? 0 : 1

  name                 = "${local.name}-app"
  assume_role_policy   = data.aws_iam_policy_document.irsa_assume[0].json
  max_session_duration = 3600
  tags                 = local.tags
}

resource "aws_iam_role_policy_attachment" "app" {
  count      = var.create_iam_user ? 0 : 1
  role       = aws_iam_role.app[0].name
  policy_arn = aws_iam_policy.app.arn
}

# ------------------------------------- dev: programmatic user (blocked in prod)

resource "aws_iam_user" "app" {
  count = var.create_iam_user ? 1 : 0
  name  = "${local.name}-app"
  tags  = local.tags
}

resource "aws_iam_user_policy_attachment" "app" {
  count      = var.create_iam_user ? 1 : 0
  user       = aws_iam_user.app[0].name
  policy_arn = aws_iam_policy.app.arn
}

resource "aws_iam_access_key" "app" {
  count = var.create_iam_user ? 1 : 0
  user  = aws_iam_user.app[0].name
}

# Access key is delivered via Secrets Manager, not via terraform output.
resource "aws_secretsmanager_secret" "app_credentials" {
  count                   = var.create_iam_user ? 1 : 0
  name                    = "${local.name}/app/credentials"
  recovery_window_in_days = 0
  tags                    = local.tags
}

resource "aws_secretsmanager_secret_version" "app_credentials" {
  count     = var.create_iam_user ? 1 : 0
  secret_id = aws_secretsmanager_secret.app_credentials[0].id
  secret_string = jsonencode({
    aws_access_key_id     = aws_iam_access_key.app[0].id
    aws_secret_access_key = aws_iam_access_key.app[0].secret
  })
}
```

