## `modules/app-infra/outputs.tf`

```hcl
output "bucket_name" {
  description = "Assets bucket name."
  value       = aws_s3_bucket.assets.bucket
}

output "bucket_arn" {
  value = aws_s3_bucket.assets.arn
}

output "replica_bucket_arn" {
  description = "Replica bucket ARN, null when replication is disabled."
  value       = try(aws_s3_bucket.replica[0].arn, null)
}

output "db_endpoint" {
  description = "RDS endpoint (host:port)."
  value       = aws_db_instance.this.endpoint
}

output "db_security_group_id" {
  value = aws_security_group.db.id
}

output "db_secret_arn" {
  description = "Secrets Manager ARN holding the connection string. Value is never emitted."
  value       = aws_secretsmanager_secret.db.arn
}

output "app_role_arn" {
  description = "IRSA role ARN, null in dev."
  value       = try(aws_iam_role.app[0].arn, null)
}

output "app_user_credentials_secret_arn" {
  description = "Secrets Manager ARN for the dev programmatic credentials, null in prod."
  value       = try(aws_secretsmanager_secret.app_credentials[0].arn, null)
}

output "kms_key_arn" {
  value = local.kms_key_arn
}
```

